package lombok.javac.handlers;

import com.sun.tools.javac.code.Flags;
import com.sun.tools.javac.tree.JCTree;
import com.sun.tools.javac.tree.JCTree.*;
import com.sun.tools.javac.util.List;
import com.sun.tools.javac.util.ListBuffer;
import com.sun.tools.javac.util.Name;
import lombok.AccessLevel;
import lombok.ConfigurationKeys;
import lombok.experimental.StandardException;
import lombok.core.AST.Kind;
import lombok.core.AnnotationValues;
import lombok.core.configuration.AllowHelper;
import lombok.core.configuration.FlagUsageType;
import lombok.delombok.LombokOptionsFactory;
import lombok.javac.Javac;
import lombok.javac.JavacAnnotationHandler;
import lombok.javac.JavacNode;
import lombok.javac.JavacTreeMaker;
import lombok.javac.handlers.JavacHandlerUtil.*;
import lombok.spi.Provides;

import static lombok.javac.Javac.*;
import static lombok.javac.handlers.JavacHandlerUtil.*;

@Provides
public class HandleStandardException extends JavacAnnotationHandler<StandardException> {
	@Override
	public void handle(AnnotationValues<StandardException> annotation, JCAnnotation ast, JavacNode annotationNode) {
		FlagUsageType fut = annotationNode.getAst().readConfiguration(ConfigurationKeys.STANDARD_EXCEPTION_FLAG_USAGE);
		if (fut == null && AllowHelper.isAllowable(ConfigurationKeys.STANDARD_EXCEPTION_FLAG_USAGE)) {
			annotationNode.addError("Use of @StandardException is disabled by default. Please add '" + ConfigurationKeys.STANDARD_EXCEPTION_FLAG_USAGE.getKeyName() + " = " + FlagUsageType.ALLOW + "' to 'lombok.config' if you want to enable is.");
		}
		if (fut != null) {
			String flagged = "Use of @StandardException is flagged according to lombok configuration.";
			if (fut == FlagUsageType.WARNING) annotationNode.addWarning(flagged);
			else if (fut == FlagUsageType.ERROR) annotationNode.addError(flagged);
		}

		deleteAnnotationIfNeccessary(annotationNode, StandardException.class);
		deleteImportFromCompilationUnit(annotationNode, "lombok.AccessLevel");
		JavacNode typeNode = annotationNode.up();

		JCClassDecl typeDeclForClassCheck;
		if (typeNode.get() instanceof JCClassDecl) {
			typeDeclForClassCheck = (JCClassDecl) typeNode.get();
		} else {
			annotationNode.addError("@StandardException is only supported on a class");
			return;
		}
		long classCheckFlags = typeDeclForClassCheck.mods.flags;
		if ((classCheckFlags & (Flags.INTERFACE | Flags.ENUM | Flags.ANNOTATION | RECORD)) != 0) {
			annotationNode.addError("@StandardException is only supported on a class");
			return;
		}

		JCTree extending = Javac.getExtendsClause((JCClassDecl) typeNode.get());
		if (extending == null) {
			annotationNode.addError("@StandardException requires that you extend a Throwable type");
			return;
		}

		AccessLevel access = annotation.getInstance().access();
		if (access == null) access = AccessLevel.PUBLIC;
		if (access == AccessLevel.NONE) {
			annotationNode.addError("AccessLevel.NONE is not valid here");
			access = AccessLevel.PUBLIC;
		}

		JavacTreeMaker maker = typeNode.getTreeMaker();
		Class<?>[][] wantedByKind = new Class<?>[][] {
			new Class<?>[0],
			new Class<?>[] {String.class},
			new Class<?>[] {Throwable.class},
			new Class<?>[] {String.class, Throwable.class}
		};
		for (int constructorKind = 0; constructorKind < 4; constructorKind++) {
			boolean msgParam = (constructorKind & 1) == 1;
			boolean causeParam = constructorKind >= 2;
			Class<?>[] wanted = wantedByKind[constructorKind];
			boolean constructorExists = false;
			JavacNode searchNode = upToTypeNode(typeNode);
			if (searchNode != null && searchNode.get() instanceof JCClassDecl) {
				for (JCTree def : ((JCClassDecl) searchNode.get()).defs) {
					if (!(def instanceof JCMethodDecl)) continue;
					JCMethodDecl md = (JCMethodDecl) def;
					if (!md.name.contentEquals("<init>") || (md.mods.flags & Flags.GENERATEDCONSTR) != 0) continue;
					List<JCVariableDecl> existingParams = md.params;
					boolean paramsAreEqual;
					if (existingParams == null) {
						paramsAreEqual = wanted.length == 0;
					} else if (existingParams.size() != wanted.length) {
						paramsAreEqual = false;
					} else {
						paramsAreEqual = true;
						for (int i = 0; i < existingParams.size(); i++) {
							JCVariableDecl param = existingParams.get(i);
							if (param.vartype == null || !typeMatches(wanted[i], searchNode, param.vartype)) {
								paramsAreEqual = false;
								break;
							}
						}
					}
					if (!paramsAreEqual) continue;
					constructorExists = true;
					break;
				}
			}
			if (constructorExists) continue;

			List<JCStatement> statements;
			if (constructorKind == 0) {
				List<JCExpression> args = List.<JCExpression>of(maker.Literal(CTC_BOT, null), maker.Literal(CTC_BOT, null));
				JCStatement thisCall = maker.Exec(maker.Apply(List.<JCExpression>nil(), maker.Ident(typeNode.toName("this")), args));
				statements = List.of(thisCall);
			} else if (constructorKind == 1) {
				List<JCExpression> args = List.<JCExpression>of(maker.Ident(typeNode.toName("message")), maker.Literal(CTC_BOT, null));
				JCStatement thisCall = maker.Exec(maker.Apply(List.<JCExpression>nil(), maker.Ident(typeNode.toName("this")), args));
				statements = List.of(thisCall);
			} else if (constructorKind == 2) {
				Name causeName = typeNode.toName("cause");
				JCExpression causeDotGetMessage = maker.Apply(List.<JCExpression>nil(), maker.Select(maker.Ident(causeName), typeNode.toName("getMessage")), List.<JCExpression>nil());
				JCExpression msgExpression = maker.Conditional(maker.Binary(CTC_NOT_EQUAL, maker.Ident(causeName), maker.Literal(CTC_BOT, null)), causeDotGetMessage, maker.Literal(CTC_BOT, null));
				List<JCExpression> args = List.<JCExpression>of(msgExpression, maker.Ident(causeName));
				JCStatement thisCall = maker.Exec(maker.Apply(List.<JCExpression>nil(), maker.Ident(typeNode.toName("this")), args));
				statements = List.of(thisCall);
			} else {
				Name causeName = typeNode.toName("cause");
				Name superName = typeNode.toName("super");
				List<JCExpression> superArgs = List.<JCExpression>of(maker.Ident(typeNode.toName("message")));
				JCStatement superCall = maker.Exec(maker.Apply(List.<JCExpression>nil(), maker.Ident(superName), superArgs));
				JCExpression causeNotNull = maker.Binary(CTC_NOT_EQUAL, maker.Ident(causeName), maker.Literal(CTC_BOT, null));
				JCStatement initCauseCall = maker.Exec(maker.Apply(List.<JCExpression>nil(), maker.Select(maker.Ident(superName), typeNode.toName("initCause")), List.<JCExpression>of(maker.Ident(causeName))));
				JCStatement initCause = maker.If(causeNotNull, initCauseCall, null);
				statements = List.of(superCall, initCause);
			}

			boolean addConstructorProperties;
			if ((!msgParam && !causeParam) || isLocalType(typeNode) || !LombokOptionsFactory.getDelombokOptions(typeNode.getContext()).getFormatPreferences().generateConstructorProperties()) {
				addConstructorProperties = false;
			} else {
				Boolean addCp = typeNode.getAst().readConfiguration(ConfigurationKeys.ANY_CONSTRUCTOR_ADD_CONSTRUCTOR_PROPERTIES);
				if (addCp != null) addConstructorProperties = addCp.booleanValue();
				else addConstructorProperties = Boolean.FALSE.equals(typeNode.getAst().readConfiguration(ConfigurationKeys.ANY_CONSTRUCTOR_SUPPRESS_CONSTRUCTOR_PROPERTIES));
			}

			ListBuffer<JCVariableDecl> params = new ListBuffer<JCVariableDecl>();
			if (msgParam) {
				Name fieldName = typeNode.toName("message");
				long flags = addFinalIfNeeded(Flags.PARAMETER, typeNode.getContext());
				JCExpression pType = genJavaLangTypeRef(typeNode, "String");
				JCVariableDecl param = maker.VarDef(maker.Modifiers(flags), fieldName, pType, null);
				params.append(param);
			}
			if (causeParam) {
				Name fieldName = typeNode.toName("cause");
				long flags = addFinalIfNeeded(Flags.PARAMETER, typeNode.getContext());
				JCExpression pType = genJavaLangTypeRef(typeNode, "Throwable");
				JCVariableDecl param = maker.VarDef(maker.Modifiers(flags), fieldName, pType, null);
				params.append(param);
			}

			JCModifiers mods = maker.Modifiers(toJavacModifier(access), List.<JCAnnotation>nil());
			if (addConstructorProperties) {
				JCExpression constructorPropertiesType = chainDots(typeNode, "java", "beans", "ConstructorProperties");
				ListBuffer<JCExpression> fieldNames = new ListBuffer<JCExpression>();
				if (msgParam) fieldNames.append(maker.Literal("message"));
				if (causeParam) fieldNames.append(maker.Literal("cause"));
				JCExpression fieldNamesArray = maker.NewArray(null, List.<JCExpression>nil(), fieldNames.toList());
				JCAnnotation constructorPropertiesAnn = maker.Annotation(constructorPropertiesType, List.of(fieldNamesArray));
				mods.annotations = mods.annotations.append(constructorPropertiesAnn);
			}

			JCMethodDecl constr = recursiveSetGeneratedBy(maker.MethodDef(mods, typeNode.toName("<init>"),
				null, List.<JCTypeParameter>nil(), params.toList(), List.<JCExpression>nil(),
				maker.Block(0L, statements), null), annotationNode);
			injectMethod(typeNode, constr);
		}
	}

	public static boolean isLocalType(JavacNode type) {
		Kind kind = type.up().getKind();
		if (kind == Kind.COMPILATION_UNIT) return false;
		if (kind == Kind.TYPE) return isLocalType(type.up());
		return true;
	}
}

